-- ----------------------------
-- Table structure for inspection_record
-- ----------------------------
DROP TABLE IF EXISTS `inspection_record`;
CREATE TABLE `inspection_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `summary_id` bigint NOT NULL COMMENT '主表ID（inspection_summary.id）',
  `defect_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '不良项名称',
  `upload_flag` tinyint(1) DEFAULT '0' COMMENT '上传标志，true表示已上传',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='镜检单条记录表';

-- ----------------------------
-- Records of inspection_record
-- ----------------------------
BEGIN;
INSERT INTO `inspection_record` (`id`, `summary_id`, `defect_name`, `upload_flag`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (1, 121, '121', 0, NULL, '2025-07-22 13:46:26', NULL, '2025-07-22 13:46:25');
COMMIT;

-- ----------------------------
-- Table structure for inspection_report
-- ----------------------------
DROP TABLE IF EXISTS `inspection_report`;
CREATE TABLE `inspection_report` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `summary_id` bigint NOT NULL COMMENT '主表ID（inspection_summary.id）',
  `work_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工单号',
  `report_time` datetime NOT NULL COMMENT '报工时间',
  `report_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '报工类型，如“自动”、“手动”等',
  `quantity` decimal(10,2) NOT NULL COMMENT '报工数量',
  `result_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '返回json内容',
  `success_flag` tinyint(1) DEFAULT '1' COMMENT '成功状态，true表示成功',
  `defect_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '不良项备注',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='报工记录表';

