-- ----------------------------
-- Table structure for inspection_summary
-- ----------------------------
DROP TABLE IF EXISTS `inspection_summary`;
CREATE TABLE `inspection_summary` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `work_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工单号',
  `total_quantity` int NOT NULL COMMENT '总数量',
  `defective_total` int DEFAULT '0' COMMENT '不合格总数',
  `defect_1` int DEFAULT '0' COMMENT '不良1',
  `defect_2` int DEFAULT '0' COMMENT '不良2',
  `defect_3` int DEFAULT '0' COMMENT '不良3',
  `defect_4` int DEFAULT '0' COMMENT '不良4',
  `defect_5` int DEFAULT '0' COMMENT '不良5',
  `defect_6` int DEFAULT '0' COMMENT '不良6',
  `defect_7` int DEFAULT '0' COMMENT '不良7',
  `defect_8` int DEFAULT '0' COMMENT '不良8',
  `defect_9` int DEFAULT '0' COMMENT '不良9',
  `defect_10` int DEFAULT '0' COMMENT '不良10',
  `defect_11` int DEFAULT '0' COMMENT '不良11',
  `defect_12` int DEFAULT '0' COMMENT '不良12',
  `defect_13` int DEFAULT '0' COMMENT '不良13',
  `defect_14` int DEFAULT '0' COMMENT '不良14',
  `defect_15` int DEFAULT '0' COMMENT '不良15',
  `defect_16` int DEFAULT '0' COMMENT '不良16',
  `defect_17` int DEFAULT '0' COMMENT '不良17',
  `defect_18` int DEFAULT '0' COMMENT '不良18',
  `defect_19` int DEFAULT '0' COMMENT '不良19',
  `defect_20` int DEFAULT '0' COMMENT '不良20',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `all_defect_items` text COMMENT '全部缺陷项',
  `stop_time` text COMMENT '暂停时间',
  `api_detail` text COMMENT 'api反馈',
  `qr_code` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '二维码',
  `color` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '颜色',
  `api_report` text,
  `success_flag` int DEFAULT NULL,
  PRIMARY KEY (`id`,`qr_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='镜检统计主表';

-- ----------------------------
-- Records of inspection_summary
-- ----------------------------
BEGIN;
